import * as THREE from 'three';

/**
 * Helical curve starting at phase `phase`, winding `turns` full turns,
 * rising by `rise` per turn, ending at height turns*rise.
 */
class HelixCurve extends THREE.Curve {
  constructor(turns, rise, radius, phase) {
    super();
    this.turns = turns;
    this.rise = rise;
    this.radius = radius;
    this.phase = phase;
    this.height = turns * rise;
  }

  getPoint(t, optionalTarget = new THREE.Vector3()) {
    const angle = this.phase + 2 * Math.PI * this.turns * t;
    return optionalTarget.set(
      this.radius * Math.cos(angle),
      this.height * t,
      this.radius * Math.sin(angle)
    );
  }
}

/**
 * Builds a DNA double-helix hero asset.
 *
 * @param {object} [options]
 * @param {number} [options.turns=4]          Number of full helical turns.
 * @param {number} [options.rise=1.2]         Vertical distance covered per turn.
 * @param {number} [options.radius=1]         Helix radius.
 * @param {number} [options.basesPerTurn=10]  Base steps per turn (rungs per turn).
 * @returns {THREE.Group} Group containing two backbone tubes and rung meshes
 *                        named "rung-<i>".
 */
export function buildHelix({
  turns = 4,
  rise = 1.2,
  radius = 1,
  basesPerTurn = 10
} = {}) {
  const group = new THREE.Group();
  group.name = 'dna-helix';

  const curveA = new HelixCurve(turns, rise, radius, 0);
  const curveB = new HelixCurve(turns, rise, radius, Math.PI);

  const tubeGeometry = new THREE.TubeGeometry(curveA, Math.ceil(turns * 32), radius * 0.12, 12, false);
  const backboneMaterial = new THREE.MeshStandardMaterial({ color: 0x66ccff, metalness: 0.3, roughness: 0.5 });

  const strandA = new THREE.Mesh(tubeGeometry, backboneMaterial);
  strandA.name = 'backbone-a';
  group.add(strandA);

  const strandB = new THREE.Mesh(
    new THREE.TubeGeometry(curveB, Math.ceil(turns * 32), radius * 0.12, 12, false),
    backboneMaterial
  );
  strandB.name = 'backbone-b';
  group.add(strandB);

  const totalSteps = turns * basesPerTurn;
  const rungGeometry = new THREE.CylinderGeometry(radius * 0.05, radius * 0.05, 2 * radius, 8);
  const rungMaterial = new THREE.MeshStandardMaterial({ color: 0xffaa44, metalness: 0.1, roughness: 0.7 });
  const up = new THREE.Vector3(0, 1, 0);

  for (let i = 0; i < totalSteps; i++) {
    const t = i / totalSteps;
    const a = curveA.getPoint(t);
    const b = curveB.getPoint(t);

    const rung = new THREE.Mesh(rungGeometry, rungMaterial);
    rung.name = `rung-${i}`;

    // Orient the unit-height cylinder so its axis spans a -> b, then place it
    // at the segment midpoint.
    const dir = new THREE.Vector3().subVectors(b, a);
    rung.quaternion.setFromUnitVectors(up, dir.clone().normalize());
    rung.position.copy(a).add(b).multiplyScalar(0.5);

    group.add(rung);
  }

  return group;
}

/**
 * Returns the two world-space endpoints of rung `i` in `group`.
 *
 * @param {THREE.Group} group  Group produced by buildHelix.
 * @param {number} i           Index of the rung ("rung-<i>").
 * @returns {[THREE.Vector3, THREE.Vector3]} World-space endpoints.
 */
export function rungEndpoints(group, i) {
  const rung = group.getObjectByName(`rung-${i}`);
  if (!rung) {
    throw new Error(`No rung named "rung-${i}" in group`);
  }
  group.updateWorldMatrix(true, true);
  const halfHeight = rung.geometry.parameters.height / 2;
  const top = new THREE.Vector3(0, halfHeight, 0).applyMatrix4(rung.matrixWorld);
  const bottom = new THREE.Vector3(0, -halfHeight, 0).applyMatrix4(rung.matrixWorld);
  return [top, bottom];
}

