import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildHelix, rungEndpoints } from '../src/dna.js';

const TAU = Math.PI * 2;

function normalizeAngle(a) {
  return ((a % TAU) + TAU) % TAU;
}

describe('buildHelix', () => {
  it('creates one rung per base step', () => {
    const group = buildHelix();
    const rungs = group.children.filter((c) => c.name.startsWith('rung-'));
    expect(rungs.length).toBe(4 * 10);
  });

  it('places rungs 0, 7 and 19 on the two helices, PI out of phase', () => {
    const turns = 4;
    const rise = 1.2;
    const radius = 1;
    const basesPerTurn = 10;
    const totalSteps = turns * basesPerTurn;
    const group = buildHelix({ turns, rise, radius, basesPerTurn });

    for (const i of [0, 7, 19]) {
      const t = i / totalSteps;
      const expectedPhase = normalizeAngle(TAU * turns * t);

      const [a, b] = rungEndpoints(group, i);
      for (const p of [a, b]) {
        // Endpoint lies on a cylinder of the given helix radius.
        expect(Math.hypot(p.x, p.z) - radius).toBeLessThan(1e-6);
        // Its angular position matches one of the two strands.
        const phase = normalizeAngle(Math.atan2(p.z, p.x));
        const deltaA = Math.abs(phase - expectedPhase);
        const deltaB = Math.abs(normalizeAngle(phase - expectedPhase - Math.PI));
        expect(Math.min(deltaA, deltaB)).toBeLessThan(1e-6);
      }

      // The two endpoints are on opposite strands: phases differ by PI.
      const phaseA = normalizeAngle(Math.atan2(a.z, a.x));
      const phaseB = normalizeAngle(Math.atan2(b.z, b.x));
      expect(Math.abs(normalizeAngle(phaseB - phaseA) - Math.PI)).toBeLessThan(1e-6);
    }
  });

  it('keeps both endpoints of each rung at the same height', () => {
    const group = buildHelix();
    const totalSteps = 4 * 10;
    for (let i = 0; i < totalSteps; i++) {
      const [a, b] = rungEndpoints(group, i);
      expect(Math.abs(a.y - b.y)).toBeLessThan(1e-9);
    }
  });

  it('steps rung heights by rise / basesPerTurn', () => {
    const turns = 4;
    const rise = 1.2;
    const basesPerTurn = 10;
    const group = buildHelix({ turns, rise, basesPerTurn });
    const expectedStep = rise / basesPerTurn;
    for (let i = 1; i < turns * basesPerTurn; i++) {
      const [, prev] = rungEndpoints(group, i - 1);
      const [, cur] = rungEndpoints(group, i);
      expect(cur.y - prev.y - expectedStep).toBeLessThan(1e-9);
      expect(cur.y - prev.y - expectedStep).toBeGreaterThan(-1e-9);
    }
  });

  it('has a total height of turns * rise', () => {
    const turns = 4;
    const rise = 1.2;
    const group = buildHelix({ turns, rise });
    const box = new THREE.Box3().setFromObject(group);
    expect(box.max.y - box.min.y - turns * rise).toBeLessThan(1e-6);
  });
});

